fn before(a: i64, b: i64, best: &[i64], ids: &[str]) -> bool {
    if best[a] != best[b] { return best[a] > best[b] }
    str_cmp(ids[a], ids[b]) < 0
}

fn run() -> Result<i64, str> {
    let roster_text = read_file("./data/roster.txt")?
    let score_text = read_file("./data/scores.csv")?

    let rl = str_split(roster_text, "\n")
    let ids = arr_repeat("", 0)
    let names = arr_repeat("", 0)
    for i in 0..len(rl) {
        let line = rl[i]
        if len(line) > 0 {
            let sp = str_index_of(line, " ")
            if sp >= 0 {
                ids = arr_push(ids, str_slice(line, 0, sp))
                names = arr_push(names, str_slice(line, sp + 1, len(line)))
            }
        }
    }

    let n = len(ids)
    let best = arr_repeat(-1, n)
    let lines = arr_unique(str_split(score_text, "\n"))
    let ignored = 0
    for i in 0..len(lines) {
        let line = lines[i]
        if len(line) > 0 {
            let c = str_index_of(line, ",")
            if c >= 0 {
                let sid = str_slice(line, 0, c)
                let sc = parse_int_or(str_slice(line, c + 1, len(line)), -1)
                match arr_index_of(ids, sid) {
                    Some(p) => {
                        if sc > best[p] { best[p] = sc }
                    }
                    None => {
                        ignored = ignored + 1
                    }
                }
            }
        }
    }

    let order = arr_repeat(0, 0)
    for i in 0..n {
        if best[i] >= 0 { order = arr_push(order, i) }
    }
    let m = len(order)
    for i in 1..m {
        let j = i
        while j > 0 && before(order[j], order[j - 1], &best, &ids) {
            let t = order[j]
            order[j] = order[j - 1]
            order[j - 1] = t
            j = j - 1
        }
    }

    let out = ""
    for k in 0..m {
        let idx = order[k]
        out = out + to_str(k + 1) + ". " + names[idx] + " " + to_str(best[idx]) + "\n"
    }
    for i in 0..n {
        if best[i] < 0 { out = out + names[i] + " -\n" }
    }

    write_file("./out/ranking.txt", out)?
    println("ignored: {to_str(ignored)}")
    Ok(0)
}

fn main() -> i64 {
    match run() {
        Ok(c) => c
        Err(e) => {
            eprintln("error: {e}")
            1
        }
    }
}
